"""Portable viewer for the separately validated native Stata heat branch."""
from __future__ import annotations
import base64
import gzip
import hashlib
import json
from pathlib import Path
import subprocess

import numpy as np
import pandas as pd

ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/stata_key_results'


def capture_stata_environment(server_python):
    code="import importlib.metadata as m,json,sys,platform;print(json.dumps({'python':sys.version,'platform':platform.platform(),'packages':{d.metadata['Name']:d.version for d in m.distributions()}}))"
    record=json.loads(subprocess.run([str(server_python),'-c',code],capture_output=True,text=True,check=True).stdout)
    record['stata_observed']={'version':'17','flavor':'IC','installation':'/Applications/Stata/StataBE.app','transport':'Real local MCP stdio; no fallback'}
    ado=Path.home()/'Library/Application Support/Stata/ado/plus';sources={}
    for path in sorted(ado.rglob('*')):
        if path.is_file() and path.suffix in ['.ado','.mata'] and (path.name.startswith(('reghdfe','ftools','ms_')) or path.stem in ['esttab','estout']):
            sources[str(path)]={'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'header':path.read_text(errors='replace').splitlines()[0] if path.stat().st_size else ''}
    record['package_sources']=sources
    (OUT/'mcp/environment.json').write_text(json.dumps(record,indent=2)+'\n')
    (OUT/'mcp/requirements.txt').write_text('\n'.join(name+'=='+version for name,version in sorted(record['packages'].items(),key=lambda item:item[0].lower()))+'\n')
    return record


def build_stata_key_report():
    proof=json.loads((OUT/'verification.json').read_text());assert proof['status']=='passed'
    specs=json.loads((OUT/'specifications.json').read_text());effects=pd.read_csv(OUT/'estimates.csv',dtype={'sector_id':str})
    comparisons=pd.read_csv(OUT/'vce_convention_comparison.csv')
    native={path.stem:path.read_text() for path in sorted((OUT/'native_tables').glob('*.html'))}
    sectors={}
    for spec in specs:
        if spec['context'] not in sectors:
            source=pd.read_csv(ROOT/spec['sample_csv'],dtype={'sector_id':str})
            sectors[spec['context']]=source.drop_duplicates('sector_id').set_index('sector_id').sector.to_dict()
    downloads={name:base64.b64encode(gzip.compress((OUT/name).read_bytes(),mtime=0)).decode() for name in ['estimates.csv','control_coefficients.csv','joint_tests.csv','specifications.csv','singleton_sample_comparison.csv','vce_convention_comparison.csv','stata_python_coverage.csv','verification.json','do/key_results.do','do/postprocess.mata.do','native/master_stata_output.txt','mcp/environment.json','mcp/requirements.txt']}
    payload={'specs':specs,'effects':effects.replace({np.nan:None}).to_dict('records'),'native':native,'downloads':downloads,'sectors':sectors}
    packed=base64.b64encode(gzip.compress(json.dumps(payload,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode(),mtime=0)).decode()
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Native Stata key-results check</title><style>body{font:15px system-ui;max-width:1240px;margin:32px auto;padding:0 20px;background:#f7faf8;color:#173b3b}p{line-height:1.55;max-width:1100px}select,button{font:inherit;padding:8px;margin:5px}table{border-collapse:collapse;width:100%;background:white}th,td{padding:8px;border-bottom:1px solid #dbe7e3;text-align:right;vertical-align:top}th:first-child,td:first-child{text-align:left}thead{background:#e1eeea}.scroll{overflow:auto}.status{background:#e1eeea;padding:15px}.small{font-size:12px;color:#405d5d}.sig{color:#17634f;font-weight:650}.caution{background:#fff1d8;padding:12px}summary{cursor:pointer;font-weight:600;margin:18px 0}code{font-size:12px}</style><h1>Native Stata key-results check</h1><p class="status">99 fixed targets · Stata 17/IC · reghdfe 6.13.1 · real MCP stdio · separately executed Python compatibility port: passed.</p><p>This branch preserves the existing project results. Every coefficient comes from native <code>reghdfe</code>. Calendar covariance matrices and industry totals are computed in Mata from those native residuals and the complete design geometry, then checked independently with Python QR and calendar-keyed score products.</p><p>The fixed matrix covers official aggregate GVA, complete VA12/20, official IIP and IIP6/18 monthly/quarterly. Both short SA and YoY NSA growth receive all/event/strict long-weather comparisons. Full-control and industry-interaction checks follow the downloadable 99-target protocol; three official-total YoY SA comparisons are retained. No targets were chosen by sign or significance. Strict masks use every output period in [t−h,t], with h=4 quarters or 12 months, and output growth was computed before filtering.</p><p class="caution">Native sector-cluster covariance fails for the 12 H1 interaction targets: Stata reports a highly singular matrix and posts zero covariance. Its raw output is retained; native H1 SE/p-values are unavailable. H1 main inference uses joint actual-calendar DK covariance and the complete baseline-plus-industry cross terms. Common-slope main inference uses sector CR1 with the project's full design K; national series use calendar HAC. These are descriptive sensitivity checks, not stationarity or causal certification.</p><p>Native reghdfe's nested-FE degrees-of-freedom adjustment is retained separately. On usable common panel fits, native SEs are 0.8705–0.9887 times the full-K project-convention SEs; the independent port verifies the exact multiplier. No default singleton deletion occurred in this matrix. Every native e(sample) row was checked; the reproducible script also retains exact-eligible companions if future native defaults remove rows.</p><div id="selectors"></div><p><label>Display <select id="view"><option value="main">Main project convention</option><option value="native">Native reghdfe convention</option><option value="calendar_h1">Calendar h</option><option value="calendar_h2">Calendar 2h</option><option value="project_cluster">Full-K sector CR1 sensitivity</option></select></label></p><p id="selection" class="small"></p><div class="scroll"><table><thead id="head"></thead><tbody id="rows"></tbody></table></div><p class="small">Cells: coefficient (SE), unrounded nominal p-value, +0.1°C scale, exact-sample mean growth/SD, N and distinct dates. Stars use strict p&lt;.01/.05/.10; unavailable inference receives no stars. Current air temperature is in °C; rain is per100mm, RH in percentage points, wind m/s and PM2.5 per10µg/m³. Every fitted model retains industry×season and common year fixed effects.</p><details><summary>Original native esttab table</summary><div id="native" class="scroll"></div><p class="small">This table uses native default samples and VCE. H1 tables intentionally show coefficients only. It is distinct from the main convention shown above.</p></details><details><summary>Reproducibility and downloads</summary><p>Run <code>uv run python scripts/stata_key_results.py</code> to prepare the frozen-source inputs/do-file. In an isolated environment, run <code>uv run --no-project --python 3.12 --with-requirements outputs/stata_key_results/mcp/requirements.txt python scripts/stata_mcp_client.py --receipt heat_key_results --timeout 1800 --do-file outputs/stata_key_results/do/key_results.do</code>. A licensed Stata installation and matching reghdfe/ftools/estout packages are required. Then independently execute <code>uv run python scripts/verify_stata_key_results.py</code>. Regenerating paths in a clone is intentional; no source refresh is performed.</p><div id="downloads"></div><p>Primary implementation references: <a href="https://scorreia.com/help/reghdfe.html">reghdfe help</a>, <a href="https://scorreia.com/software/reghdfe/faq.html">nested FE correction</a>, <a href="https://www.stata.com/manuals/m-5svd.pdf">Mata thin SVD</a>. The native log, do-files, full covariance CSVs, exact source data and MCP protocol receipts are retained under <code>outputs/stata_key_results/</code>.</p></details><script>const packed="PACKED";let data;const $=id=>document.getElementById(id);const keys=['context','outcome','control_set','structure'];const variants=['all_eligible','event_dates_excluded','strict_growth_window_clean'];const labels={all_eligible:'All eligible',event_dates_excluded:'Exclude event dates',strict_growth_window_clean:'Clean output window'};const esc=x=>String(x).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));function fmt(x){return x===null||!Number.isFinite(x)?'unavailable':Math.abs(x)<.0001&&x!==0?x.toExponential(2):x.toFixed(4)}async function inflate(t){const b=Uint8Array.from(atob(t),c=>c.charCodeAt(0));return new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text()}function draw(){let s=data.specs;for(let i=0;i<keys.length;i++){const k=keys[i],sel=$(k),old=sel.value,opts=[...new Set(s.map(r=>r[k]))];sel.innerHTML=opts.map(o=>'<option>'+esc(o)+'</option>').join('');if(opts.includes(old))sel.value=old;s=s.filter(r=>r[k]===sel.value)}const ids=new Set(s.map(r=>r.target_id)),view=$('view').value;let e=data.effects.filter(r=>ids.has(r.target_id)&&r.run_variant==='native_default'&&(view==='main'?r.main_inference:r.method===view));const present=variants.filter(v=>s.some(r=>r.sample_variant===v));$('head').innerHTML='<tr><th>Industry</th>'+present.map(v=>'<th>'+labels[v]+'</th>').join('')+'</tr>';const sectors=[...new Set(e.map(r=>r.sector_id))].sort();$('rows').innerHTML=sectors.map(sid=>'<tr><th>'+esc(sid)+'</th>'+present.map(v=>{const r=e.find(r=>r.sector_id===sid&&r.sample_variant===v);if(!r)return'<td>Not included in this fixed comparison</td>';const p=r.p_value,star=p===null?'':p<.01?'***':p<.05?'**':p<.10?'*':'';return'<td><span class="'+(p!==null&&p<.05?'sig':'')+'">'+fmt(r.coefficient)+star+' ('+fmt(r.std_error)+')</span><br>p '+fmt(p)+' · +0.1°C '+fmt(r.effect_0p1c)+'<br><span class="small">Mean '+fmt(r.mean_y)+' / SD '+fmt(r.sd_y)+'<br>N '+r.n_obs+' · dates '+r.n_periods+' · inference df '+r.inference_df+'<br>'+esc(r.method)+(r.inference_status==='available'?'':' · '+esc(r.inference_status))+'</span></td>'}).join('')+'</tr>').join('');if(!e.length)$('rows').innerHTML='<tr><td>No such covariance display exists for this fixed comparison.</td></tr>';$('selection').textContent=keys.map(k=>$(k).value).join(' · ')+' · '+s.length+' target(s); no hidden recomputation';$('native').innerHTML=data.native[keys.map(k=>$(k).value).join('__')]||'No native table';}async function start(){data=JSON.parse(await inflate(packed));$('selectors').innerHTML=keys.map(k=>'<label>'+k+' <select id="'+k+'"></select></label>').join('');keys.forEach(k=>$(k).onchange=draw);$('view').onchange=draw;draw();$('downloads').innerHTML=Object.keys(data.downloads).map(n=>'<button data-file="'+esc(n)+'">'+esc(n)+'</button>').join('');$('downloads').onclick=async e=>{const n=e.target.dataset.file;if(!n)return;const text=await inflate(data.downloads[n]);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download=n.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}start().catch(e=>{$('selection').textContent='Unable to load embedded results: '+e.message;throw e});</script></html>'''
    page=page.replace("'<tr><th>'+esc(sid)+'</th>'", "'<tr><th>'+esc((data.sectors[$('context').value]||{})[sid]||sid)+'</th>'")
    before="+fmt(r.std_error)+')</span><br>p '+fmt(p)"
    after="+fmt(r.std_error)+')</span>'+(r.structure==='H1'?'<br><span class=\"small\">Base '+fmt(r.baseline)+' + industry Δ '+fmt(r.industry_delta)+'</span>':'')+'<br>p '+fmt(p)"
    assert before in page
    page=page.replace(before,after)
    page=page.replace("' · inference df '+r.inference_df", "' · inference df '+r.inference_df+' · residual time df '+r.time_residual_df")
    path=ROOT/'outputs/stata_key_results.html';path.write_text(page.replace('PACKED',packed))
    (OUT/'report_manifest.json').write_text(json.dumps({'status':'built_from_independently_verified_native_arrays','html_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'native_tables':len(native),'targets':len(specs),'verification_sha256':hashlib.sha256((OUT/'verification.json').read_bytes()).hexdigest()},indent=2)+'\n')
    print(f'Built {path} with {len(native)} native esttab tables.',flush=True)
    return path


if __name__=='__main__':build_stata_key_report()
